create view "photoobj" AS SELECT * FROM PhotoObjAll WHERE mode IN (1, 2);

create view "photoprimary" AS SELECT * FROM PhotoObjAll WHERE mode = 1;

create view "photosecondary" AS SELECT * FROM PhotoObjAll WHERE mode = 2;

create view "photofamily" AS SELECT * FROM PhotoObjAll WHERE mode = 3;

create view "star" AS SELECT * FROM PhotoPrimary WHERE type = 6;

create view "galaxy" AS SELECT * FROM PhotoPrimary WHERE type = 3;

create view "phototag" AS SELECT "objid", "skyversion", "run", "rerun", "camcol", "field", "obj", "mode", "nchild", "type", "clean", "probpsf", "insidemask", "flags", "flags_u", "flags_g", "flags_r", "flags_i", "flags_z", "psfmag_u", "psfmag_g", "psfmag_r", "psfmag_i", "psfmag_z", "psfmagerr_u", "psfmagerr_g", "psfmagerr_r", "psfmagerr_i", "psfmagerr_z", "petromag_u", "petromag_g", "petromag_r", "petromag_i", "petromag_z", "petromagerr_u", "petromagerr_g", "petromagerr_r", "petromagerr_i", "petromagerr_z", "petror50_r", "petror90_r", u AS "modelmag_u", g AS "modelmag_g", r AS "modelmag_r", i AS "modelmag_i", z AS "modelmag_z", err_u AS "modelmagerr_u", err_g AS "modelmagerr_g", err_r AS "modelmagerr_r", err_i AS "modelmagerr_i", err_z AS "modelmagerr_z", "cmodelmag_u", "cmodelmag_g", "cmodelmag_r", "cmodelmag_i", "cmodelmag_z", "cmodelmagerr_u", "cmodelmagerr_g", "cmodelmagerr_r", "cmodelmagerr_i", "cmodelmagerr_z", "mrrcc_r", "mrrccerr_r", "mrrccpsf_r", "fracdev_u", "fracdev_g", "fracdev_r", "fracdev_i", "fracdev_z", "psffwhm_u", "psffwhm_g", "psffwhm_r", "psffwhm_i", "psffwhm_z", "resolvestatus", "thingid", "balkanid", "nobserve", "ndetect", "calibstatus_u", "calibstatus_g", "calibstatus_r", "calibstatus_i", "calibstatus_z", "ra", "dec", "cx", "cy", "cz", "extinction_u", "extinction_g", "extinction_r", "extinction_i", "extinction_z", "htmid", "fieldid", "specobjid", (CASE WHEN mRrCc_r > 0 THEN SQRT(mRrCc_r / 2.0) ELSE 0 END) AS size FROM PhotoObjAll;

create view "startag" AS SELECT * FROM PhotoTag WHERE type = 6 AND mode = 1;

create view "galaxytag" AS SELECT * FROM PhotoTag WHERE type = 3 AND mode = 1;

create view "sky" AS SELECT * FROM PhotoPrimary WHERE type = 8;

create view "unknown" AS SELECT * FROM PhotoPrimary WHERE NOT type IN (3, 6, 8);

create view "specphoto" AS SELECT * FROM SpecPhotoAll WHERE sciencePrimary = 1 AND mode = 1;

create view "specobj" AS SELECT * FROM specObjAll WHERE sciencePrimary = 1;

create view "photoflags" AS SELECT name, value, description FROM DataConstants WHERE field = 'PhotoFlags' AND name <> '';

create view "columns" AS SELECT * FROM DBColumns;

create view "segue1specobjall" AS SELECT s.* FROM specObjAll AS s JOIN plateX AS p ON s.plateId = p.plateId WHERE p.programName LIKE 'seg%' AND NOT p.programName LIKE 'segue2%';

create view "segue2specobjall" AS SELECT s.* FROM specObjAll AS s JOIN plateX AS p ON s.plateId = p.plateId WHERE p.programName LIKE 'segue2%';

create view "seguespecobjall" AS SELECT s.* FROM specObjAll AS s JOIN plateX AS p ON s.plateId = p.plateId WHERE p.programName LIKE 'seg%';

create view "sdsstile" AS SELECT * FROM sdssTileAll WHERE untiled = 0;

create view "sdsstilingboundary" AS SELECT * FROM sdssTilingGeometry WHERE isMask = 0;

create view "sdsstilingmask" AS SELECT * FROM sdssTilingGeometry WHERE isMask = 1;

create view "specialtarget1" AS SELECT name, value, description FROM DataConstants WHERE field = 'SpecialTarget1' AND name <> '';

create view "bosstarget1" AS SELECT name, value, description FROM DataConstants WHERE field = 'BossTarget1' AND name <> '';

create view "ancillarytarget1" AS SELECT name, value, description FROM DataConstants WHERE field = 'AncillaryTarget1' AND name <> '';

create view "ancillarytarget2" AS SELECT name, value, description FROM DataConstants WHERE field = 'AncillaryTarget2' AND name <> '';

create view "regionconvex" AS SELECT regionid, convexid, patchid AS patch, type, radius, ra, dec, x, y, z, c, htmid, convexString FROM RegionPatch;

create view "ebosstarget0" AS SELECT name, value, description FROM DataConstants WHERE field = 'eBossTarget0' AND name <> '';

create view "sdssvbosstarget0" AS SELECT name, value, description FROM DataConstants WHERE field = 'sdssvBossTarget0' AND name <> '';

create view "photomode" AS SELECT name, CAST(value AS INT) AS value, description FROM DataConstants WHERE field = 'PhotoMode' AND name <> '';

create view "phototype" AS SELECT name, CAST(value AS INT) AS value, description FROM DataConstants WHERE field = 'PhotoType' AND name <> '';

create view "masktype" AS SELECT name, CAST(value AS INT) AS value, description FROM DataConstants WHERE field = 'MaskType' AND name <> '';

create view "fieldquality" AS SELECT name, CAST(value AS INT) AS value, description FROM DataConstants WHERE field = 'FieldQuality' AND name <> '';

create view "pspstatus" AS SELECT name, CAST(value AS INT) AS value, description FROM DataConstants WHERE field = 'PspStatus' AND name <> '';

create view "framesstatus" AS SELECT name, CAST(value AS INT) AS value, description FROM DataConstants WHERE field = 'FramesStatus' AND name <> '';

create view "holetype" AS SELECT name, CAST(value AS INT) AS value, description FROM DataConstants WHERE field = 'HoleType' AND name <> '';

create view "sourcetype" AS SELECT name, CAST(value AS INT) AS value, description FROM DataConstants WHERE field = 'SourceType' AND name <> '';

create view "programtype" AS SELECT name, CAST(value AS INT) AS value, description FROM DataConstants WHERE field = 'ProgramType' AND name <> '';

